local GlassKilnDoorMaker = {}
local PRODUCTS = {
    iron_glasskilndoor = { name = "Železni vrata za steklarsko pec", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni vrata za steklarsko pec za steklarje." },
    bronze_glasskilndoor = { name = "Bronast vrata za steklarsko pec", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast vrata za steklarsko pec za steklarje." },
    silver_glasskilndoor = { name = "Srebrn vrata za steklarsko pec", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vrata za steklarsko pec za steklarje." },
    gilded_glasskilndoor = { name = "Pozlačen vrata za steklarsko pec", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vrata za steklarsko pec za steklarje." },
    jewel_set_glasskilndoor = { name = "Draguljast vrata za steklarsko pec", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast vrata za steklarsko pec za steklarje." },
    royal_sovereign_glasskilndoor = { name = "Kraljevski suveren vrata za steklarsko pec", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren vrata za steklarsko pec z biseri za krono." },
}
local BUILDINGS = {
    glasskilndoor_workshop = { name = "Glasskilndoor delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glasskilndoor_house = { name = "Glasskilndoor hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glasskilndoor_atelier = { name = "Mojstrski glasskilndoor atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glasskilndoor_palace = { name = "Suverena glasskilndoor palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassKilnDoorMaker.ironStock = 16; GlassKilnDoorMaker.bronzeStock = 14; GlassKilnDoorMaker.woodStock = 10; GlassKilnDoorMaker.leatherStock = 8; GlassKilnDoorMaker.silverStock = 8; GlassKilnDoorMaker.goldStock = 6; GlassKilnDoorMaker.jewelStock = 4; GlassKilnDoorMaker.pearlStock = 4
GlassKilnDoorMaker.productStock = {}; GlassKilnDoorMaker.buildings = {}; GlassKilnDoorMaker.maker = nil; GlassKilnDoorMaker.activeMaking = {}; GlassKilnDoorMaker.totalProducts = 0; GlassKilnDoorMaker.dayTimer = 0
function GlassKilnDoorMaker.init() GlassKilnDoorMaker.ironStock=16; GlassKilnDoorMaker.bronzeStock=14; GlassKilnDoorMaker.woodStock=10; GlassKilnDoorMaker.leatherStock=8; GlassKilnDoorMaker.silverStock=8; GlassKilnDoorMaker.goldStock=6; GlassKilnDoorMaker.jewelStock=4; GlassKilnDoorMaker.pearlStock=4; GlassKilnDoorMaker.productStock={}; GlassKilnDoorMaker.buildings={}; GlassKilnDoorMaker.maker=nil; GlassKilnDoorMaker.activeMaking={}; GlassKilnDoorMaker.totalProducts=0; GlassKilnDoorMaker.dayTimer=0; print("[GlassKilnDoorMaker] Royal Glass Kiln Door Maker System initialized (6 products, 4 buildings)") end
function GlassKilnDoorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassKilnDoorMaker.maker={name=n or ("Vratar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vratar najet: %s (spretnost: %d)",GlassKilnDoorMaker.maker.name,s),"success") end; return true end
function GlassKilnDoorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassKilnDoorMaker.build(id) local ok,e=GlassKilnDoorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassKilnDoorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassKilnDoorMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassKilnDoorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassKilnDoorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassKilnDoorMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassKilnDoorMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassKilnDoorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassKilnDoorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassKilnDoorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassKilnDoorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassKilnDoorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassKilnDoorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassKilnDoorMaker.buildings==0 then return false,"Potrebna vratna delavnica" end; if not GlassKilnDoorMaker.maker then return false,"Potreben vratar" end; return true end
function GlassKilnDoorMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassKilnDoorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassKilnDoorMaker.ironStock=GlassKilnDoorMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassKilnDoorMaker.bronzeStock=GlassKilnDoorMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassKilnDoorMaker.woodStock=GlassKilnDoorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassKilnDoorMaker.leatherStock=GlassKilnDoorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassKilnDoorMaker.silverStock=GlassKilnDoorMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassKilnDoorMaker.goldStock=GlassKilnDoorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassKilnDoorMaker.jewelStock=GlassKilnDoorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassKilnDoorMaker.pearlStock=GlassKilnDoorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassKilnDoorMaker.maker then t=math.max(1,t-math.floor(GlassKilnDoorMaker.maker.skill/13)) end; table.insert(GlassKilnDoorMaker.activeMaking,{id="glasskilndoor_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassKilnDoorMaker.completeMaking(m) local q=1.0+(GlassKilnDoorMaker.getQualityBonus()/100); if GlassKilnDoorMaker.maker then q=q+(GlassKilnDoorMaker.maker.skill/140) end; q=math.min(2.5,q); GlassKilnDoorMaker.productStock[m.productType]=(GlassKilnDoorMaker.productStock[m.productType] or 0)+m.quantity; GlassKilnDoorMaker.totalProducts=GlassKilnDoorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassKilnDoorMaker.maker then GlassKilnDoorMaker.maker.itemsMade=GlassKilnDoorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassKilnDoorMaker.maker.skill=math.min(100,GlassKilnDoorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrata izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glasskilndoor.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function GlassKilnDoorMaker.update(dt) if not _G.state then return end; GlassKilnDoorMaker.dayTimer=GlassKilnDoorMaker.dayTimer+dt; if GlassKilnDoorMaker.dayTimer>=30 then GlassKilnDoorMaker.dayTimer=0; for i=#GlassKilnDoorMaker.activeMaking,1,-1 do local m=GlassKilnDoorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassKilnDoorMaker.completeMaking(m); table.remove(GlassKilnDoorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassKilnDoorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassKilnDoorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassKilnDoorMaker.getStats() return {ironStock=GlassKilnDoorMaker.ironStock,bronzeStock=GlassKilnDoorMaker.bronzeStock,woodStock=GlassKilnDoorMaker.woodStock,leatherStock=GlassKilnDoorMaker.leatherStock,silverStock=GlassKilnDoorMaker.silverStock,goldStock=GlassKilnDoorMaker.goldStock,jewelStock=GlassKilnDoorMaker.jewelStock,pearlStock=GlassKilnDoorMaker.pearlStock,productStock=GlassKilnDoorMaker.productStock,numBuildings=#GlassKilnDoorMaker.buildings,hasMaker=GlassKilnDoorMaker.maker~=nil,makerName=GlassKilnDoorMaker.maker and GlassKilnDoorMaker.maker.name or "—",makerSkill=GlassKilnDoorMaker.maker and GlassKilnDoorMaker.maker.skill or 0,activeMaking=#GlassKilnDoorMaker.activeMaking,totalProducts=GlassKilnDoorMaker.totalProducts} end
return GlassKilnDoorMaker
